-- Preserva registros existentes. Não aprova comprovantes nem registra receitas.
create unique index sj_comprovante_ativo_por_viagem on public.comprovantes_motoristas(viagem_id) where viagem_id is not null and status<>'rejeitado';
create policy sj_comprovante_admin_insert on public.comprovantes_motoristas for insert to authenticated with check(
 public.is_sj_admin() and user_id=(select auth.uid()) and enviado_por=(select auth.uid()) and status='pendente' and arquivo_path like (select auth.uid())::text||'/%' and viagem_id is not null
 and exists(select 1 from public.viagens v where v.id=viagem_id and v.user_id=comprovantes_motoristas.user_id and v.motorista_id=comprovantes_motoristas.motorista_id));
create policy sj_comprovante_motorista_vinculado on public.comprovantes_motoristas for select to authenticated using(exists(select 1 from public.motoristas m where m.id=comprovantes_motoristas.motorista_id and m.user_id=comprovantes_motoristas.user_id and m.auth_user_id=(select auth.uid()) and m.status='ativo'));
create policy sj_comprovante_storage_admin_insert on storage.objects for insert to authenticated with check(bucket_id='sj-comprovantes' and public.is_sj_admin() and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy sj_comprovante_storage_motorista_vinculado on storage.objects for select to authenticated using(bucket_id='sj-comprovantes' and exists(select 1 from public.comprovantes_motoristas c join public.motoristas m on m.id=c.motorista_id and m.user_id=c.user_id where c.arquivo_path=objects.name and m.auth_user_id=(select auth.uid()) and m.status='ativo'));
create policy sj_comprovante_limpar_upload_orfao on storage.objects for delete to authenticated using(bucket_id='sj-comprovantes' and (storage.foldername(name))[1]=(select auth.uid())::text and (public.is_sj_admin() or exists(select 1 from public.motoristas m where m.auth_user_id=(select auth.uid()) and m.status='ativo')) and not exists(select 1 from public.comprovantes_motoristas c where c.arquivo_path=objects.name));
